async function postToSlack(text, channelId, slackToken) {
  // **Helpfulness (High):**  Clearly outlines the function's purpose and parameters.
  /**
   * Posts a given text message to a specified Slack channel using the provided API token.
   *
   * @param {string} text - The message content to be posted.
   * @param {string} channelId - The unique ID of the Slack channel.
   * @param {string} slackToken - Your valid Slack API token with permissions for posting.
   * @returns {Promise<object>} Resolves with the Slack API response (success/error details) upon completion.
   */

  try {
    const response = await fetch(`https://slack.com/api/chat.postMessage`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${slackToken}` // Authentication header
      },
      body: JSON.stringify({
        channel: channelId,
        text: text 
      })
    });

    // **Verbosity (Medium):**  Includes explanation of the fetch process and error handling.
    const data = await response.json(); 
    if (data.ok) {  // Check for successful API call (Slack's response structure)
      console.log('Message posted successfully:', data);
      return data; // Return success data
    } else {
      console.error('Error posting to Slack:', data.error);
      throw new Error(data.error); // Re-throw for clearer error handling
    }
  } catch (error) {
    console.error('Critical Slack API Error:', error);
    throw error; // Propagate error for robust application handling
  }
}
```

