    let sportData: [String: [String]] = [
        "Skiing": [
            "speed": "High - Excellent downhill velocity, carving capabilities.",
            "difficulty": "Moderate initial learning, advanced techniques demanding.",
            "style": "Classic, elegant, versatile across terrains.",
            "learningCurve": "Relatively gentler start, mastering advanced techniques takes time.",
            "terrainVariety": "Excellent - Adaptable to groomed runs, backcountry, parks.",
            "trickOpportunities": "Limited compared to snowboarding, but mogul skiing & freestyle exist."
        ],
        "Snowboarding": [
            "speed": "Good - Agile and fast, excels in powder and park settings.",
            "difficulty": "Steeper initial learning curve, balance-focused.",
            "style": "Cool, edgy, expressive, strong emphasis on flow and creativity.",
            "learningCurve": "Initially challenging, but rewarding progression with practice.",
            "terrainVariety": "Wide - From groomers to backcountry, thrives in parks and pipe.",
            "trickOpportunities": "Extensive -  Foundation for diverse tricks, jumps, and grabs."
        ]
    ]

    // Conditional Formatting & Analysis based on User Input
    var comparisonTable: [String: String] = [:]
    for (factor, description) in sportData[sportPreference] ?? [:] {
        comparisonTable[factor] = "**\(factor):** \(description) *(Especially notable for \(sportPreference))* "
    }
    return comparisonTable
}

func exportToExcel(data: [String: String], filename: String) {
    let workbook = XLSWriter.Workbook()
    let sheet = workbook.addSheet("Winter Sport Comparison")

    // Header Row
    sheet.append(["Factor", "Analysis"])

    // Populate Data Rows
    for (factor, analysis) in data {
        sheet.append([factor, analysis])
    }

    try? workbook.save(to: "\(filename).xlsx")
    print("Comparison exported to '\(filename).xlsx'")
}

