import { Injectable } from '@nestjs/common';
import { AuthGuard, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { ROLE_PERMISSIONS } from './constants'; // Assuming constants file for predefined roles & permissions

@Injectable()
export class RolesAuthGuard extends AuthGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    const user = context.switchToHttp().getRequest().user; 

    if (!user || !requiredRoles) return false;

    return this.prisma.user.findUnique({ where: { id: user.id } }).then(userEntity => {
      return requiredRoles.some(role => userEntity?.roles.includes(role) && ROLE_PERMISSIONS[role].some(perm => userEntity.permissions.includes(perm)));
    });
  }
}

// Example ROLE_PERMISSIONS (in constants file):
const ROLE_PERMISSIONS: Record<string, string[]> = {
  ADMIN: ['createPost', 'editPost', 'deletePost', 'manageUsers'],
  EDITOR: ['createPost', 'editPost'],
  USER: ['readPost'],
  // ...more roles and their permissions
};
```

**Explanation (for context, NOT to be included in final `index.js`):**

*   **RolesAuthGuard:** A custom `AuthGuard` leveraging `@nestjs/common` and `Reflector` to dynamically fetch required roles from method decorators (`@Roles('ADMIN')` etc.).
*   **prisma Integration:** Uses `PrismaService` to fetch user data (roles and permissions) from the database for real-time authorization checks.
*   **`ROLE_PERMISSIONS`:**  A centralized constant defines role-permission mappings, promoting maintainability.
*   **Logic:** Checks if the logged-in user's roles match *any* of the required roles AND possess the necessary permissions within that role. Returns `true` if authorized, `false` otherwise.

This structure allows seamless integration into NestJS routes and controllers via decorators like `@UseGuards(RolesAuthGuard

